head.b:skin:
/* Balaio v0.2.0-rc.6 — código original, MIT. Inter e Newsreader: SIL OFL 1.1.
   Edite as variáveis abaixo para personalizar a identidade do blog. */
/* Controles do Designer do Blogger.
<Variable name="papercolor" description="Fundo da página" type="color" default="#fffefb" value="#fffefb"/>
<Variable name="inkcolor" description="Texto principal" type="color" default="#202c28" value="#202c28"/>
<Variable name="mutedcolor" description="Texto secundário" type="color" default="#5d6b64" value="#5d6b64"/>
<Variable name="accentcolor" description="Links e botões" type="color" default="#22614c" value="#22614c"/>
<Variable name="linecolor" description="Divisórias suaves" type="color" default="#dce5df" value="#dce5df"/>
<Variable name="washcolor" description="Superfície verde pastel" type="color" default="#edf5ef" value="#edf5ef"/>
<Variable name="sandcolor" description="Card areia pastel" type="color" default="#f8f1e7" value="#f8f1e7"/>
<Variable name="bluecolor" description="Card azul pastel" type="color" default="#eef2f6" value="#eef2f6"/>
<Variable name="interfacefont" description="Fonte da interface" type="font" default="normal 400 17px Inter, system-ui, sans-serif" value="normal 400 17px Inter, system-ui, sans-serif"/>
<Variable name="readingfont" description="Fonte de posts e páginas" type="font" default="normal 400 22px Newsreader, serif" value="normal 400 22px Newsreader, serif"/>
*/
:root {
  --paper:$papercolor;
  --ink:$inkcolor;
  --muted:$mutedcolor;
  --accent:$accentcolor;
  --line:$linecolor;
  --wash:$washcolor;
  --card-sand:$sandcolor;
  --card-blue:$bluecolor;
  --reading-width:760px;
  --interface-font:$interfacefont;
  --reading-font:$readingfont;
  --width:1120px;
}
* {
  box-sizing:border-box;
}
[hidden] {
  display:none!important;
}
body {
  margin:0;
  background:var(--paper);
  color:var(--ink);
  font:var(--interface-font);
  line-height:1.65;
}
a {
  color:var(--accent);
  text-decoration:none;
}
a:hover {
  text-decoration:underline;
}
img {
  max-width:100%;
  height:auto;
}
button,input {
  font:inherit;
}
a:focus-visible,input:focus-visible {
  outline:3px solid var(--accent);
  outline-offset:4px;
}
.wrap {
  width:min(var(--width),calc(100% - 48px));
  margin-inline:auto;
}
.skip {
  position:absolute;
  top:-100px;
  left:16px;
  background:var(--ink);
  color:white;
  padding:10px;
  z-index:10;
}
.skip:focus {
  top:10px;
}
.masthead {
  padding:32px 0 20px;
  border-bottom:1px solid var(--line);
}
.masthead .widget,.masthead .section {
  margin:0;
}
.masthead-top > * {
  min-width:0;
}
.masthead-top {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:24px;
}
.brand {
  font:var(--interface-font);
  font-weight:750;
  font-size:clamp(26px,4vw,38px);
  line-height:1.2;
  letter-spacing:-.045em;
  color:var(--ink);
  overflow-wrap:anywhere;
}
.description {
  color:var(--muted);
  margin:10px 0 0;
  max-width:60ch;
  font-size:15px;
}
.search {
  display:flex;
  gap:8px;
  align-items:center;
}
.search input {
  width:180px;
  min-width:0;
  border:1px solid var(--line);
  border-radius:4px;
  background:var(--paper);
  padding:8px 12px;
}
.search button {
  background:var(--accent);
  color:white;
  border:0;
  border-radius:4px;
  padding:9px 14px;
  cursor:pointer;
}
.navigation {
  padding-top:20px;
}
.navigation ul {
  display:flex;
  flex-wrap:wrap;
  gap:12px 24px;
  list-style:none;
  margin:0;
  padding:0;
}
.navigation a {
  display:inline-flex;
  padding:6px 10px;
  border-radius:6px;
  overflow-wrap:anywhere;
  font-size:14px;
  color:var(--ink);
}
.navigation a[aria-current='page'] {
  background:var(--wash);
  text-decoration:underline;
  text-underline-offset:4px;
}
.widget h2 {
  font:var(--reading-font);
  font-weight:700;
  font-size:21px;
  line-height:1.3;
  margin:0 0 16px;
}
.intro {
  padding:48px 0 32px;
  max-width:700px;
}
.intro h1 {
  font:var(--reading-font);
  font-weight:400;
  font-size:clamp(32px,4vw,46px);
  line-height:1.2;
  letter-spacing:-.025em;
  margin:0;
}
.intro p {
  color:var(--muted);
  margin:16px 0 0;
  max-width:52ch;
}
.eyebrow {
  font-size:11px;
  font-weight:650;
  text-transform:uppercase;
  letter-spacing:.14em;
  color:var(--accent);
  margin-bottom:16px;
}
.content-grid {
  display:grid;
  grid-template-columns:minmax(0,1fr);
  padding:36px 0 64px;
}
.content-grid>* {
  min-width:0;
}
.section-title {
  font:var(--interface-font);
  font-weight:600;
  font-size:22px;
  line-height:1.3;
  letter-spacing:-.04em;
  margin:0 0 24px;
}
.opening-cards {
  display:grid;
  grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));
  gap:16px;
  margin-bottom:24px;
}
.opening-cards .post-card {
  display:flex;
  flex-direction:column;
  gap:0;
  padding:18px;
  background:var(--wash);
  border:1px solid var(--line);
  border-radius:12px;
}
.opening-cards .post-card:nth-child(2) {
  background:var(--card-sand);
}
.opening-cards .post-card:nth-child(3) {
  background:var(--card-blue);
}
.opening-cards .post-image-link {
  order:-1;
  margin:0 0 8px;
}
.opening-cards .post-image {
  aspect-ratio:4/3;
  border-radius:7px;
}
.opening-cards .post-card h2 {
  font-size:25px;
}
.opening-cards .post-summary {
  font-size:14px;
}
.opening-cards .meta {
  font-size:11px;
}
.opening-cards .post-copy {
  display:flex;
  flex-direction:column;
  flex:1;
}
.opening-cards .meta {
  margin-top:12px;
}
.posts {
  display:flex;
  flex-direction:column;
  gap:0;
}
.post-card {
  display:grid;
  grid-template-columns:minmax(0,1fr) 180px;
  gap:24px;
  min-width:0;
  border-top:1px solid var(--line);
  padding:28px 0;
}
.post-card h2 {
  overflow-wrap:anywhere;
}
.post-copy {
  min-width:0;
}
.post-copy:only-child {
  grid-column:1/-1;
}
.post-card h2 {
  font:var(--reading-font);
  font-weight:600;
  font-size:28px;
  line-height:1.25;
  margin:10px 0;
  letter-spacing:-.02em;
}
.post-card h2 a {
  color:var(--ink);
}
.post-image-link {
  align-self:start;
  margin-top:12px;
}
.post-image {
  display:block;
  width:100%;
  aspect-ratio:4/3;
  object-fit:cover;
  border-radius:2px;
}
.post-summary {
  color:var(--muted);
  margin:12px 0;
  font-size:15px;
}
.meta {
  display:flex;
  flex-wrap:wrap;
  gap:6px 12px;
  font-size:13px;
  color:var(--muted);
}
.labels {
  display:flex;
  flex-wrap:wrap;
  gap:8px;
  font-size:12px;
  margin:12px 0;
  text-transform:uppercase;
  letter-spacing:.06em;
}
.site-footer {
  padding:20px 0;
  border-top:1px solid var(--line);
  font-size:13px;
  color:var(--muted);
}
.site-footer a {
  color:inherit;
}
.pager {
  display:flex;
  justify-content:space-between;
  gap:16px;
  margin-top:36px;
  border-top:1px solid var(--line);
  padding-top:20px;
  font-size:14px;
}
.article {
  width:100%;
  max-width:var(--reading-width);
  margin:0 auto;
  padding:48px 0 64px;
}
.article h1 {
  overflow-wrap:anywhere;
  font:var(--reading-font);
  font-weight:700;
  font-size:clamp(34px,5vw,54px);
  line-height:1.13;
  margin:0 0 24px;
}
.post-body {
  font:var(--reading-font);
  line-height:1.75;
  overflow-wrap:anywhere;
  margin-top:32px;
}
.post-body h2,.post-body h3 {
  line-height:1.3;
  margin-top:1.8em;
}
.post-body h2 {
  font-size:1.4em;
}
.post-body h3 {
  font-size:1.18em;
}
.post-body a {
  text-decoration:underline;
}
.post-body img {
  height:auto;
}
.post-body figure {
  max-width:100%;
  margin:24px 0;
}
.post-body figcaption {
  color:var(--muted);
  font:var(--interface-font);
  font-size:14px;
  line-height:1.6;
  margin-top:8px;
}
.post-body video {
  max-width:100%;
  height:auto;
}
.post-body .video {
  aspect-ratio:16/9;
  width:100%;
}
.post-body .video iframe {
  display:block;
  width:100%;
  height:100%;
  border:0;
}
.post-body iframe {
  max-width:100%;
}
.post-body blockquote {
  border-left:3px solid var(--accent);
  margin:24px 0;
  padding:4px 24px;
  color:var(--muted);
}
.post-body pre {
  overflow:auto;
  background:var(--wash);
  padding:20px;
  font:14px/1.6 monospace;
}
.post-body code {
  font-family:monospace;
}
.post-body table {
  display:block;
  overflow:auto;
  max-width:100%;
  border-collapse:collapse;
}
.post-body th,.post-body td {
  border:1px solid var(--line);
  padding:8px 12px;
}
.comments {
  margin-top:48px;
  border-top:1px solid var(--line);
  padding-top:24px;
}
.comment {
  padding:20px 0;
  border-bottom:1px solid var(--line);
}
.comment-body {
  overflow-wrap:anywhere;
}
.empty {
  padding:32px;
  background:var(--wash);
}
.article-grid {
  grid-template-columns:minmax(0,1fr);
}
#sidebar,.widget.BlogSearch,.widget.BlogArchive,.widget.FeaturedPost,.widget.ReportAbuse,.widget.Profile,.widget.Attribution {
  display:none;
}
@media(min-width:801px) and (max-width:1050px) {
  .opening-cards {
    grid-template-columns:1fr;
  }
  .opening-cards .post-card {
    display:grid;
    grid-template-columns:minmax(0,1fr) 150px;
    gap:20px;
  }
  .opening-cards .post-image-link {
    order:0;
    margin:0;
  }
}
@media(max-width:800px) {
  .wrap {
    width:calc(100% - 32px);
  }
  .masthead {
    padding:20px 0 16px;
  }
  .masthead-top {
    gap:16px;
    align-items:flex-start;
    flex-direction:column;
  }
  .search {
    width:100%;
  }
  .search input {
    flex:1;
  }
  .navigation {
    padding-top:12px;
  }
  .intro {
    padding:28px 0 16px;
  }
  .opening-cards {
    margin-bottom:16px;
  }
  .pager {
    margin-top:24px;
    padding-top:16px;
  }
  .content-grid {
    grid-template-columns:1fr;
    gap:24px;
    padding:24px 0 40px;
  }
  .post-card {
    grid-template-columns:minmax(0,1fr) 160px;
    gap:20px;
  }
  .article {
    padding:20px 0;
  }
}
@media(max-width:600px) {
  .opening-cards {
    grid-template-columns:1fr;
  }
  .opening-cards .post-image-link {
    max-width:none;
  }
  .opening-cards .post-image {
    aspect-ratio:16/9;
  }
}
@media(max-width:480px) {
  .post-card {
    grid-template-columns:1fr;
    gap:12px;
  }
  .post-image-link {
    margin-top:0;
    max-width:240px;
  }
  .post-card h2 {
    font-size:25px;
  }
  .navigation ul {
    gap:10px 18px;
  }
}
@media(prefers-reduced-motion:reduce) {
  * {
    scroll-behavior:auto!important;
  }
}
@media print {
  .masthead,.site-footer,.pager,.comments,.skip {
    display:none;
  }
  .content-grid {
    display:block;
    padding:0;
  }
  .wrap,.article {
    width:100%;
    max-width:none;
  }
  .post-body {
    font-size:12pt;
  }
  body {
    background:white;
    color:black;
  }
}

b:includable.script:
//
(() => {
  'use strict';
  const list = document.getElementById('postlist');
  if (!list || !window.fetch || !window.AbortController) return;
  const blog = list.closest('.widget');
  const older = blog && blog.querySelector('.pager a[rel="next"]');
  if (!older) return;
  const target = Math.min(40, Math.max(2, Number(list.dataset.homePosts) || 10));
  const pageLimit = Math.min(6, Math.max(0, Number(list.dataset.pageLimit) || 0));
  const seen = new Set();
  const visited = new Set();

  function localURL(value, base) {
    if (typeof value !== "string" || !value.trim()) return null;
    try {
      const url = new URL(value, base);
      return url.origin === location.origin && /^https?:$/.test(url.protocol) ? url : null;
    } catch (_) { return null; }
  }
  function postURL(card, base) {
    const link = card.querySelector('h2 a');
    return link && localURL(link.getAttribute('href'), base);
  }
  function key(url) { return url.origin + url.pathname; }
  for (const card of blog.querySelectorAll('.post-card')) {
    const url = postURL(card, location.href);
    if (url) seen.add(key(url));
  }
  if (!seen.size || seen.size >= target || !pageLimit) return;

  function node(tag, className, text) {
    const element = document.createElement(tag);
    if (className) element.className = className;
    if (text != null) element.textContent = text;
    return element;
  }
  // Rebuild only text, links and the thumbnail; never insert fetched scripts or HTML.
  function copyCard(source, url, base) {
    const card = node('article', 'post-card');
    const copy = node('div', 'post-copy');
    const sourceLabels = source.querySelectorAll('.labels a');
    if (sourceLabels.length) {
      const labels = node('div', 'labels');
      for (const sourceLink of sourceLabels) {
        const labelURL = localURL(sourceLink.getAttribute('href'), base);
        if (!labelURL) continue;
        const link = node('a', '', sourceLink.textContent);
        link.href = labelURL.href;
        link.rel = 'tag';
        labels.append(link);
      }
      if (labels.childElementCount) copy.append(labels);
    }
    const heading = node('h2');
    const link = node('a', '', source.querySelector('h2 a').textContent);
    link.href = url.href;
    heading.append(link);
    copy.append(heading);
    const summary = source.querySelector('.post-summary');
    if (summary) copy.append(node('p', 'post-summary', summary.textContent));
    const meta = node('div', 'meta');
    for (const span of source.querySelectorAll('.meta > span')) {
      meta.append(node('span', '', span.textContent));
    }
    if (meta.childElementCount) copy.append(meta);
    card.append(copy);
    const sourceImage = source.querySelector('img.post-image');
    if (sourceImage) {
      try {
        const imageURL = new URL(sourceImage.getAttribute('src'), base);
        if (imageURL.protocol === 'https:') {
          const imageLink = node('a', 'post-image-link');
          imageLink.href = url.href;
          imageLink.tabIndex = -1;
          imageLink.setAttribute('aria-hidden', 'true');
          const image = node('img', 'post-image');
          image.alt = '';
          image.width = 640;
          image.height = 480;
          image.loading = 'lazy';
          image.decoding = 'async';
          image.src = imageURL.href;
          imageLink.append(image);
          card.append(imageLink);
        }
      } catch (_) { /* A missing thumbnail never removes the post. */ }
    }
    return card;
  }

  async function fillHome() {
    let next = localURL(older.getAttribute('href'), location.href);
    list.setAttribute('aria-busy', 'true');
    try {
      for (let page = 0; next && page < pageLimit && seen.size < target; page++) {
        next.searchParams.set('m', '0');
        next.searchParams.set('max-results', String(target - seen.size));
        if (visited.has(next.href)) break;
        visited.add(next.href);
        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), 8000);
        let markup;
        try {
          const response = await fetch(next.href, {signal: controller.signal, credentials: 'omit', redirect: 'error'});
          if (!response.ok) throw new Error('Page unavailable');
          markup = await response.text();
        } finally { clearTimeout(timer); }
        // A template keeps fetched styles, images and scripts inert.
        const template = document.createElement('template');
        template.innerHTML = markup;
        const source = template.content;
        const cards = [...source.querySelectorAll('.posts > .post-card, .opening-cards > .post-card')];
        if (!cards.length) break;
        const following = source.querySelector('.pager a[rel="next"]');
        const followingURL = following && localURL(following.getAttribute('href'), next.href);
        if (following && !followingURL) break;
        const batch = document.createDocumentFragment();
        const addedURLs = new Set();
        for (const card of cards) {
          const url = postURL(card, next.href);
          if (!url) throw new Error('Invalid post link');
          if (seen.has(key(url)) || addedURLs.has(key(url))) continue;
          batch.append(copyCard(card, url, next.href));
          addedURLs.add(key(url));
        }
        list.append(batch);
        for (const url of addedURLs) seen.add(url);
        if (addedURLs.size && !blog.querySelector('.more-title')) {
          list.before(node('h2', 'section-title more-title', list.dataset.listTitle));
        }
        // Advance only after the complete page: no post is skipped at the target.
        if (followingURL) older.href = followingURL.href;
        else older.closest('.pager').hidden = true;
        next = followingURL;
        if (!addedURLs.size) break;
      }
    } catch (_) {
      // The last working native pagination link remains available on failure.
    } finally { list.removeAttribute('aria-busy'); }
  }
  fillHome();
})();
              //
